export const createPaymentUrl = async(component, paymentArea, itemId, description) => {
    const url = M.cfg.wwwroot + '/payment/gateway/airpay/pay.php?' +
        'component=' + component +
        '&paymentarea=' + paymentArea +
        '&itemid=' + itemId +
        '&description=' + description;
    return url;
};

